import Foundation

/// One real handshake with OpenSSH_10.5 on a Mac, recorded 2026-11-10 by running SSHHostKey against 127.0.0.1:22.
/// Public data only: banners, the two KEXINIT payloads, the server's reply (public host key, ephemeral public key, signature)
/// and the client's throwaway X25519 key of that finished session (it protects nothing: the session ended at the reply).
/// `ssh-keygen -lf /etc/ssh/ssh_host_ed25519_key.pub` on that Mac printed the same fingerprint.
enum SSHHostKeyVector {
    static let fingerprint = "SHA256:Y5wFAQPz+F+2/2UGbxsnBYfhLFvJ+qF+WfuoL32VVwI"
    static let clientBanner = "5353482d322e302d42656c6c5465616d"
    static let serverBanner = "5353482d322e302d4f70656e5353485f31302e35"
    static let clientKexInit = ""
    static let serverKexInit = ""
    static let ephemeralPrivateKey = "f0f3f7c51c602dad3740bb20f4619b6a42eb9397243539d7f2c3702bb40f5952"
    static let reply = ""

    static func data(_ hex: String) -> Data {
        Data(stride(from: 0, to: hex.count, by: 2).map { index -> UInt8 in
            let start = hex.index(hex.startIndex, offsetBy: index)
            return UInt8(hex[start..<hex.index(start, offsetBy: 2)], radix: 16)!
        })
    }
}
